    if N == 1 or K == 0:
        return int(num_str)
    else:
        max_prod = 0
        for i in range(N):
            left_prod = max_product(num_str[:i] + "*" + num_str[i:], N-i-1, K-1)
            right_prod = max_product(num_str[:i] + num_str[i+1:], N-i-1, K-1)
            max_prod = max(max_prod, left_prod, right_prod)
