def hanoi_double_iterative(n: int) -> int:
    if n == 1:
        return 2
    elif n == 2:
        return 6
    else:
        total_moves = 0
        for i in range(n-1):
            total_moves += pow(2, i+1)
        return 2*total_moves+1

